from datetime import datetime, timezone
from .hmac_verify import verify_signature

FIELD_MAP = {
    "soil_moisture": "moisture_fraction",
    "temp_c": "soil_temp_c",
    "ts": "observed_at",
}

def parse(payload: dict, headers: dict) -> dict:
    verify_signature(payload, headers["X-Terravex-Signature"])
    out = {}
    for src, dst in FIELD_MAP.items():
        out[dst] = payload[src]
    out["observed_at"] = datetime.fromtimestamp(payload["ts"], tz=timezone.utc)
    if not 0.0 <= out["moisture_fraction"] <= 1.0:
        raise ValueError("moisture out of range")
    return out

